<script>
  import { onMount } from 'svelte';
  import { ArrowLeft, ArrowRight, Check, CircleHelp, RotateCcw, BookOpen, SlidersHorizontal, Sparkles, Target, ChevronDown } from 'lucide-svelte';
  import { toast } from 'svelte-sonner';
  let { title, subtitle, endpoint, kind = 'practice' } = $props();
  let items = $state([]), loading = $state(true), error = $state('');
  let subject = $state('all'), topic = $state('all'), amount = $state('10'), index = $state(0), selected = $state(null), pool = $state([]);
  let finished = $state(false), score = $state(0);
  let topics = $derived([...new Set(items.filter(x=>subject==='all'||x.subject===subject).map(x=>x.topic).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja')));
  let filtered = $derived(items.filter(x=>(subject==='all'||x.subject===subject)&&(topic==='all'||x.topic===topic)));
  let q = $derived(pool[index]);
  onMount(async()=>{try{const r=await fetch(endpoint);if(!r.ok)throw new Error('教材データを読み込めませんでした');const d=await r.json();items=Array.isArray(d)?d:(d.questions||[]);}catch(e){error=e.message;}finally{loading=false;}});
  function start(){let a=[...filtered];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}pool=a.slice(0,amount==='all'?a.length:Number(amount));if(!pool.length){toast.error('この条件に合う問題がありません');return;}index=0;selected=null;score=0;finished=false;}
  function answer(i){if(selected!==null)return;selected=i;if(i===q.correct)score++;}
  function next(){if(index===pool.length-1)finished=true;else{index++;selected=null;}}
  function back(){finished=false;pool=[];selected=null;}
</script>
<svelte:head><title>{title} — MANABIXX</title><meta name="description" content={subtitle}/></svelte:head>
<div class="exam-shell">
  <header class="top"><a class="brand" href="/"><span class="mark">M<span>.</span></span><span>MANABIXX<small>LEARNING PLATFORM</small></span></a><div class="crumb">PRACTICE <i>/</i> {kind.toUpperCase()}</div><a href="/" class="home-link"><ArrowLeft size={16}/> Studyホーム</a></header>
  <main>
    {#if !pool.length&&!finished}
      <section class="intro"><div><div class="eyebrow"><Target size={14}/> PRACTICE COLLECTION / {kind.toUpperCase()}</div><h1>{title}</h1><p>{subtitle}</p></div><div class="intro-mark"><BookOpen size={31}/><span>MX / PRACTICE</span></div></section>
      {#if loading}<div class="empty">教材データを準備しています…</div>{:else if error}<div class="empty error"><CircleHelp size={20}/>{error}</div>{:else}
        <section class="overview"><div><span>AVAILABLE</span><strong>{items.length.toLocaleString('ja-JP')}</strong><small>収録問題</small></div><div><span>SCIENCE</span><strong>{items.filter(x=>x.subject==='science').length}</strong><small>理科</small></div><div><span>SOCIAL STUDIES</span><strong>{items.filter(x=>x.subject==='social').length}</strong><small>社会</small></div><div><span>SESSION</span><strong>{amount==='all'?'ALL':amount}</strong><small>出題予定数</small></div></section>
        <div class="setup-grid"><section class="setup"><div class="eyebrow">SESSION BUILDER</div><h2>演習をカスタマイズ</h2><p>今取り組みたい範囲を選択してください。</p><div class="field-grid"><label><span>教科</span><select bind:value={subject}><option value="all">すべての教科</option><option value="science">理科</option><option value="social">社会</option></select><ChevronDown size={15}/></label><label><span>分野・単元</span><select bind:value={topic}><option value="all">すべての分野</option>{#each topics as t}<option value={t}>{t}</option>{/each}</select><ChevronDown size={15}/></label><label><span>問題数</span><select bind:value={amount}><option value="10">10問</option><option value="20">20問</option><option value="30">30問</option><option value="50">50問</option><option value="all">全問</option></select><ChevronDown size={15}/></label></div><div class="setup-bottom"><div><strong>{filtered.length.toLocaleString('ja-JP')}</strong><span>問から出題</span></div><button class="primary" onclick={start}>演習を開始 <ArrowRight size={17}/></button></div></section><aside class="side-note"><div class="note-icon"><Sparkles size={18}/></div><div class="eyebrow">FOCUS ON PROGRESS</div><h3>一問ずつ、<br/>確かな理解へ。</h3><p>正解だけでなく、解説まで確認することが実力につながります。</p><div class="note-foot"><span>01</span><span>LEARN / REVIEW / GROW</span></div></aside></div>
      {/if}
    {:else if finished}
      <section class="result"><div class="eyebrow"><Sparkles size={14}/> SESSION COMPLETE</div><h1>セッション完了。</h1><p>今回の結果を振り返って、次の一歩へ。</p><div class="result-card"><span>YOUR SCORE</span><strong>{score}<small> / {pool.length}</small></strong><div class="result-track"><i style="width:{Math.round(score/pool.length*100)}%"></i></div><b>正答率 {Math.round(score/pool.length*100)}%</b></div><button class="primary" onclick={start}>もう一度挑戦 <RotateCcw size={17}/></button><button class="secondary" onclick={back}>演習設定に戻る</button></section>
    {:else if q}
      <section class="quiz"><div class="quiz-head"><button onclick={back}><ArrowLeft size={16}/> 中断して戻る</button><span>QUESTION <b>{String(index+1).padStart(2,'0')}</b> <i>/ {String(pool.length).padStart(2,'0')}</i></span></div><div class="progress"><i style="width:{(index+1)/pool.length*100}%"></i></div><div class="question-meta"><span>{q.subject==='science'?'SCIENCE / 理科':q.subject==='social'?'SOCIAL / 社会':q.subject||'PRACTICE'}</span><span>{q.topic||q.term||'GENERAL'}</span></div><div class="question-number">QUESTION {String(index+1).padStart(2,'0')}</div><h1>{q.prompt}</h1><div class="answers">{#each q.options as option,i}<button class:correct={selected!==null&&i===q.correct} class:wrong={selected===i&&selected!==q.correct} class:muted={selected!==null&&i!==q.correct&&i!==selected} disabled={selected!==null} onclick={()=>answer(i)}><span>{['A','B','C','D'][i]||i+1}</span><b>{option}</b>{#if selected!==null&&i===q.correct}<Check size={18}/>{/if}</button>{/each}</div>{#if selected!==null}<div class="explanation"><strong>{selected===q.correct?'正解。':'解説を確認しよう。'}</strong><p>{q.explanation||'この問題の解説は準備中です。正解と選択肢を確認しましょう。'}</p>{#if q.takeaway}<small>{q.takeaway}</small>{/if}{#if q.sourceNote}<small>{q.sourceNote}</small>{/if}</div><button class="primary next" onclick={next}>{index===pool.length-1?'結果を確認する':'次の問題へ'} <ArrowRight size={17}/></button>{/if}</section>
    {/if}
    <footer><a href="/">MANABIXX<span>.</span></a><span>DESIGNED FOR BETTER LEARNING.</span><a href="/releases/">更新履歴</a></footer>
  </main>
</div>
<style>
.exam-shell{min-height:100vh;background:var(--canvas);color:var(--ink)}.top{height:70px;display:flex;align-items:center;gap:40px;padding:0 max(24px,calc((100vw - 1180px)/2));background:var(--surface);border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font-weight:950;letter-spacing:.04em;font-size:12px}.brand small{display:block;font-size:7px;letter-spacing:1.5px;color:var(--muted);margin-top:3px}.mark{width:31px;height:31px;border-radius:9px;background:#181b2a;color:#fff;display:grid;place-items:center;font-size:15px}.mark span,footer a span{color:#a99dff}.crumb{font-size:8px;letter-spacing:1.6px;color:var(--muted);font-weight:800}.crumb i{font-style:normal;margin:0 8px;color:var(--brand)}.home-link{margin-left:auto;display:flex;align-items:center;gap:7px;font-size:10px;color:var(--muted);font-weight:750}main{max-width:1180px;margin:auto;padding:0 25px 35px}.intro{padding:62px 0 32px;display:flex;justify-content:space-between;align-items:center}.eyebrow{display:flex;align-items:center;gap:8px;color:var(--brand);font-size:8px;letter-spacing:1.8px;font-weight:900}.intro h1{font-size:clamp(34px,5vw,52px);letter-spacing:-2px;margin:15px 0 8px}.intro p,.setup>p,.result>p{font-size:11px;color:var(--muted)}.intro-mark{width:130px;height:130px;border:1px solid var(--line);border-radius:25px;background:linear-gradient(145deg,var(--surface),var(--brand-soft));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:var(--brand)}.intro-mark span{font-size:7px;letter-spacing:1.5px;font-weight:900}.overview{display:grid;grid-template-columns:repeat(4,1fr);background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 0;box-shadow:var(--shadow)}.overview>div{padding:0 23px;border-right:1px solid var(--line)}.overview>div:last-child{border:0}.overview span,.overview small{display:block;font-size:7px;letter-spacing:1px;color:var(--muted);font-weight:800}.overview strong{display:block;font-size:25px;margin:5px 0 1px}.setup-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:14px;margin-top:18px}.setup{padding:25px;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}.setup h2{font-size:22px;margin:10px 0 4px}.field-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin-top:25px}.field-grid label{position:relative;display:grid;gap:7px}.field-grid label>span{font-size:8px;color:var(--muted);font-weight:800}.field-grid select{appearance:none;height:42px;width:100%;padding:0 32px 0 11px;border:1px solid var(--line);border-radius:8px;background:var(--canvas);color:var(--ink);font-size:10px}.field-grid svg{position:absolute;right:10px;bottom:13px;color:var(--muted);pointer-events:none}.setup-bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);margin-top:24px;padding-top:18px}.setup-bottom>div{display:flex;align-items:baseline;gap:8px}.setup-bottom strong{font-size:23px}.setup-bottom span{font-size:9px;color:var(--muted)}.primary,.secondary{height:43px;padding:0 16px;border:0;border-radius:8px;background:var(--brand);color:white;display:inline-flex;align-items:center;justify-content:center;gap:18px;font-size:10px;font-weight:850}.side-note{position:relative;overflow:hidden;padding:23px;border-radius:14px;background:linear-gradient(150deg,#242a48,#171c30);color:white;display:flex;flex-direction:column}.note-icon{width:36px;height:36px;border-radius:10px;background:#a69bff20;color:#b9b0ff;display:grid;place-items:center;margin-bottom:22px}.side-note .eyebrow{color:#b6adff}.side-note h3{font-size:23px;line-height:1.55;margin:14px 0 7px}.side-note p{font-size:9px;line-height:1.9;color:#b7bfd4}.note-foot{display:flex;justify-content:space-between;margin-top:auto;padding-top:18px;border-top:1px solid #ffffff25;color:#aab4cc;font-size:7px;letter-spacing:1px}.empty{min-height:200px;display:flex;align-items:center;justify-content:center;gap:10px;border:1px dashed var(--line);border-radius:14px;color:var(--muted);margin-top:20px}.error{color:#c34d5a}.quiz{max-width:780px;margin:0 auto;padding:48px 0 30px}.quiz-head{display:flex;align-items:center;justify-content:space-between}.quiz-head button{display:flex;align-items:center;gap:6px;border:0;background:transparent;color:var(--muted);font-size:9px}.quiz-head>span{font-size:8px;letter-spacing:1px;color:var(--muted)}.quiz-head b{color:var(--brand)}.quiz-head i{font-style:normal}.progress{height:4px;background:var(--surface-2);margin:17px 0 40px;border-radius:9px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,#6558e8,#73cbd9);transition:width .2s}.question-meta{display:flex;gap:7px}.question-meta span{padding:6px 9px;border:1px solid var(--line);border-radius:5px;color:var(--muted);font-size:8px}.question-number{font-size:8px;letter-spacing:2px;color:var(--brand);font-weight:900;margin-top:35px}.quiz h1{font-size:clamp(22px,3.5vw,31px);line-height:1.8;margin:13px 0 25px}.answers{display:grid;gap:9px}.answers button{min-height:60px;display:flex;align-items:center;gap:15px;padding:12px 16px;text-align:left;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--ink);transition:.15s}.answers button:hover:not(:disabled){border-color:var(--brand);transform:translateX(2px)}.answers button>span{width:29px;height:29px;display:grid;place-items:center;border-radius:7px;background:var(--surface-2);font-size:9px;color:var(--muted);font-weight:850}.answers button>b{font-size:11px;font-weight:600}.answers button svg{margin-left:auto;color:#239a75}.answers button.correct{border-color:#42b796;background:#eaf8f3;color:#176b51}.answers button.wrong{border-color:#dd7580;background:#fff0f1;color:#a6323d}.answers button.muted{opacity:.45}.explanation{margin-top:17px;padding:18px 20px;border:1px solid var(--line);border-left:3px solid var(--brand);border-radius:9px;background:var(--surface)}.explanation strong{font-size:11px}.explanation p,.explanation small{display:block;font-size:10px;line-height:1.9;color:var(--muted)}.next{width:100%;margin-top:17px}.result{max-width:600px;margin:80px auto;text-align:center}.result>.eyebrow{justify-content:center}.result h1{font-size:35px;margin:13px}.result-card{margin:30px 0;padding:30px;background:var(--surface);border:1px solid var(--line);border-radius:15px}.result-card>span{font-size:8px;letter-spacing:1.5px;color:var(--muted)}.result-card>strong{display:block;font-size:55px;color:var(--brand);margin:9px}.result-card small{font-size:18px;color:var(--muted)}.result-track{height:5px;background:var(--surface-2);border-radius:5px;overflow:hidden}.result-track i{display:block;height:100%;background:var(--brand)}.result-card>b{display:block;font-size:9px;margin-top:12px}.secondary{margin-left:8px;background:var(--surface-2);color:var(--ink)}footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);margin-top:45px;padding-top:17px;color:var(--muted);font-size:7px;letter-spacing:1.2px}footer a:first-child{font-size:13px;color:var(--ink);font-weight:950}footer a:last-child{color:var(--ink);font-weight:800}
@media(max-width:800px){.setup-grid{grid-template-columns:1fr}.side-note{min-height:230px}.overview>div{padding:0 13px}}
@media(max-width:580px){.top{height:58px;padding:0 15px}.crumb{display:none}main{padding:0 14px 30px}.intro{padding:42px 0 24px}.intro h1{font-size:31px;letter-spacing:-1px}.intro p{font-size:9px;line-height:1.8;max-width:260px}.intro-mark{width:72px;height:72px;border-radius:15px}.intro-mark svg{width:22px}.intro-mark span{font-size:5px}.overview{grid-template-columns:repeat(2,1fr);gap:14px 0;padding:15px 0}.overview>div:nth-child(2){border:0}.overview>div:nth-child(3),.overview>div:nth-child(4){padding-top:10px}.overview strong{font-size:22px}.setup{padding:17px}.setup h2{font-size:19px}.field-grid{grid-template-columns:1fr;gap:12px;margin-top:20px}.field-grid select{height:43px}.setup-bottom{gap:8px}.setup-bottom strong{font-size:19px}.setup-bottom span{font-size:8px}.primary{font-size:9px;padding:0 12px;gap:9px}.side-note{padding:18px}.quiz{padding:30px 0}.progress{margin-bottom:30px}.quiz h1{font-size:21px}.answers button{min-height:56px}.result{margin:55px auto}.result h1{font-size:29px}.secondary{margin:9px 0 0;width:100%}footer{font-size:5px}footer span{display:none}.home-link{font-size:8px}}
</style>